/* Editorial English edition of the portfolio. No third-party translation service. */
window.PortfolioEN = (() => {

const schedulingIllustration=(kind,en=false)=>{
 const zh={
  priority:['先排','穩定、感情好的學生','再排','能上時間少的學生','最後','其他學生','每人至少 2 堂原老師','有人要上 5–8 堂'],
  exchange:['老師付出','整月排好每位學生','手打通知 30–60 人','學生回報','照著上課','取消變少'],
  mutual:['老師 A','空出一堂','老師群組','待課清單','老師 B','接手代課','一起達到每月 120 堂'],
  continuity:['學生課程','主要老師','代課老師','主要老師','主要老師'],
  authority:['學生時段','課程間隔','老師分配','排課草案','老師檢查與調整'],
  changing:['初次排課','臨時請假','尋找代課／補課','更新課表'],
  adoption:['自動產生課表','新工具學習','異動維護','整體負擔待驗證'],
  collaboration:['學生','主要老師','代課老師','LINE 協作與通知']
 };
 const english={
  priority:['First','Steady, close students','Then','Least available','Last','Everyone else','≥2 lessons with own instructor','Some want 5–8'],
  exchange:['She gives','Plans every student’s month','Messages 30–60 students','Students give back','Show up as planned','Fewer cancellations'],
  mutual:['Instructor A','Has an open slot','Instructors’ group','Waiting list','Instructor B','Takes the lesson','Everyone reaches 120 a month'],
  continuity:['Student lessons','Main teacher','Substitute','Main teacher','Main teacher'],
  authority:['Availability','Lesson spacing','Teacher assignment','Draft timetable','Instructor reviews and adjusts'],
  changing:['Initial plan','Absence','Find cover / make-up','Update schedule'],
  adoption:['Auto-generated plan','Tool onboarding','Change upkeep','Total effort unverified'],
  collaboration:['Student','Main instructor','Substitute','LINE communication']
 };
 const v=(en?english:zh)[kind];
 let inside='';
 if(kind==='continuity')inside='<div class="schedule-scene-label">'+v[0]+'</div><div class="schedule-scene-lessons">'+v.slice(1).map((t,i)=>'<div class="'+(i===1?'substitute':'')+'"><span>'+(i+1).toString().padStart(2,'0')+'</span><strong>'+t+'</strong></div>').join('')+'</div>';
 if(kind==='authority')inside='<div class="schedule-scene-constraints">'+v.slice(0,3).map(t=>'<span>'+t+'</span>').join('')+'</div><div class="schedule-scene-arrow">↓</div><div class="schedule-scene-draft">'+v[3]+'</div><div class="schedule-scene-arrow">↓</div><div class="schedule-scene-decision">'+v[4]+' ✓</div>';
 if(kind==='changing')inside='<div class="schedule-scene-stages">'+v.map((t,i)=>'<div class="'+(i===1?'changed':'')+'"><span>'+String(i+1).padStart(2,'0')+'</span><strong>'+t+'</strong></div>').join('')+'</div>';
 if(kind==='adoption')inside='<div class="schedule-scene-work"><div><span>−</span><strong>'+v[0]+'</strong></div><div><span>+</span><strong>'+v[1]+'</strong></div><div><span>+</span><strong>'+v[2]+'</strong></div></div><div class="schedule-scene-decision">'+v[3]+'</div>';
 if(kind==='collaboration')inside='<div class="schedule-scene-people">'+v.slice(0,3).map((t,i)=>'<div><span class="person-avatar">'+['●','◆','●'][i]+'</span><strong>'+t+'</strong></div>').join('')+'</div><div class="schedule-scene-links">↕　↕　↕</div><div class="schedule-scene-decision">'+v[3]+'</div>';
 if(kind==='priority')inside='<div class="pil-pyr"><div class="pil-pyr-shape">'+[0,1,2].map(i=>'<i class="t'+i+'"></i>').join('')+'</div><div class="pil-pyr-labels">'+[0,2,4].map((k,i)=>'<div><b>'+String(i+1).padStart(2,'0')+' '+v[k]+'</b><strong>'+v[k+1]+'</strong></div>').join('')+'</div></div><div class="pil-sc-tags"><span>'+v[6]+'</span><span>'+v[7]+'</span></div>';
 if(kind==='exchange')inside='<div class="pil-sc-swap"><div><span>'+v[0]+'</span><strong>'+v[1]+'</strong><strong>'+v[2]+'</strong></div><i>⇄</i><div class="give"><span>'+v[3]+'</span><strong>'+v[4]+'</strong><strong>'+v[5]+'</strong></div></div>';
 if(kind==='mutual')inside='<div class="pil-sc-flow"><div><span>'+v[0]+'</span><strong>'+v[1]+'</strong></div><i>→</i><div class="hub"><span>'+v[2]+'</span><strong>'+v[3]+'</strong></div><i>→</i><div><span>'+v[4]+'</span><strong>'+v[5]+'</strong></div></div><div class="schedule-scene-decision">'+v[6]+'</div>';
 return '<div class="schedule-scene schedule-scene--'+kind+'" aria-hidden="true">'+inside+'</div>';
};
const schedulingInsight=(num,label,title,copy,kind,caption,en=false)=>'<article class="schedule-insight-card"><div class="schedule-insight-copy"><div class="schedule-insight-heading"><em>'+num+'</em><span>'+label+'</span></div><h4>'+title+'</h4><p>'+copy+'</p></div><figure class="schedule-insight-figure">'+schedulingIllustration(kind,en)+'<figcaption>'+caption+'</figcaption></figure></article>';

 const section=(id,n,label,title,body)=>`<section class="story-section" id="${id}"><div class="story-kicker">${n} / ${label}</div>${title?`<h2>${title}</h2>`:''}${body}</section>`;
 const p=t=>`<p>${t}</p>`;
 const img=(file,alt,caption,cls='')=>`<figure class="${cls||'english-figure'}"><img loading="lazy" src="./${file}" alt="${alt}"><figcaption>${caption}</figcaption></figure>`;
 const evidence=(tag,title,copy)=>`<div class="english-evidence"><span>${tag}</span><h3>${title}</h3><p>${copy}</p></div>`;
 const two=(a,b)=>`<div class="english-pair">${a}${b}</div>`;
 const nav={scheduling:['Overview','Problem Discovery','Product Strategy','Design & Build','Reflection'],kiosk:['Overview','Research Approach','Product Decisions','Design & Validation','Outcome'],kds:['Context','Discovery','User Analysis','Product Decisions','Independent Design','Reflection']};
 const content={
 scheduling:()=>
 section('overview','01','PROJECT OVERVIEW','',
  p('This independent project began with a Pilates instructor’s real challenge: building the monthly timetable takes approximately 2–3 hours, followed by frequent cancellations and changes. She collects availability in LINE, arranges classes on paper, and coordinates substitute teachers in a group chat. The challenge involves not only finding open slots but making trade-offs and managing ongoing coordination.')+
  
  '<figure class="scenario-figure pilates-case-scenario"><img loading="eager" decoding="async" fetchpriority="high" width="2048" height="1536" src="./assets/pilates-scenario.webp" alt="Composite lifestyle scene of a Pilates instructor viewing the scheduling system on her phone"></figure>')+
 section('research','02','PROBLEM DISCOVERY','Scheduling is not just allocating time—it is managing relationships, earning commitment, and instructors helping each other',
  '<h3>How I researched</h3><div class="pil-methods"><div><b>01</b><strong>In-depth interviews with two instructors</strong><p>How they collect students’ availability, build the timetable, and handle changes and cover afterwards.</p></div><div><b>02</b><strong>Existing materials</strong><p>The LINE messages, paper timetable, and substitute requests in the instructors’ group used today.</p></div></div><h3>The instructor’s monthly scheduling journey</h3><div class="journey-map" role="table" aria-label="The instructor’s monthly scheduling journey"><div class="jm-label"></div><div class="jm-stage"><b>01</b><strong>Collect times</strong></div><div class="jm-stage"><b>02</b><strong>Plan the month</strong></div><div class="jm-stage"><b>03</b><strong>Find cover</strong></div><div class="jm-stage"><b>04</b><strong>Notify</strong></div><div class="jm-stage"><b>05</b><strong>Last-minute changes</strong></div><div class="jm-label">Doing</div><div class="jm-cell ">Asks students on LINE for their availability</div><div class="jm-cell ">Schedules every student by hand for the month</div><div class="jm-cell ">Hands unfillable lessons to other instructors</div><div class="jm-cell ">Tells each student their times and any cover instructor</div><div class="jm-cell ">Handles absences and no-shows</div><div class="jm-label">Feeling</div><div class="jm-feelrow"><svg class="jm-curve" viewBox="0 0 1000 120" preserveAspectRatio="none" aria-hidden="true"><polyline points="100,64 300,86 500,86 700,86 900,108"/></svg><div class="jm-feels"><div class="jm-feel" style="--lv:3"><i></i><small>OK</small></div><div class="jm-feel" style="--lv:2"><i></i><small>Tiring</small></div><div class="jm-feel" style="--lv:2"><i></i><small>Pressured</small></div><div class="jm-feel" style="--lv:2"><i></i><small>Tedious</small></div><div class="jm-feel" style="--lv:1"><i></i><small>Hardest</small></div></div></div><div class="jm-label">Pain point</div><div class="jm-cell jm-pain">Students don’t always reply on time</div><div class="jm-cell jm-pain">Retention first, ≥2 lessons with their own instructor, some want 5–8; about 2–3 hours</div><div class="jm-cell jm-pain">Posts a waiting list to the group; 120-lesson target</div><div class="jm-cell jm-pain">Types messages to 30–60 students one by one</div><div class="jm-cell jm-pain">Needs someone in right away—and has to remember who could come</div></div><ol class="journey-mobile"><li><b>01</b><strong>Collect times</strong><p>Asks students on LINE for their availability</p><p class="jm-m-feel"><em>Feeling</em>OK</p><p class="jm-m-pain"><em>Pain point</em>Students don’t always reply on time</p></li><li><b>02</b><strong>Plan the month</strong><p>Schedules every student by hand for the month</p><p class="jm-m-feel"><em>Feeling</em>Tiring</p><p class="jm-m-pain"><em>Pain point</em>Retention first, ≥2 lessons with their own instructor, some want 5–8; about 2–3 hours</p></li><li><b>03</b><strong>Find cover</strong><p>Hands unfillable lessons to other instructors</p><p class="jm-m-feel"><em>Feeling</em>Pressured</p><p class="jm-m-pain"><em>Pain point</em>Posts a waiting list to the group; 120-lesson target</p></li><li><b>04</b><strong>Notify</strong><p>Tells each student their times and any cover instructor</p><p class="jm-m-feel"><em>Feeling</em>Tedious</p><p class="jm-m-pain"><em>Pain point</em>Types messages to 30–60 students one by one</p></li><li><b>05</b><strong>Last-minute changes</strong><p>Handles absences and no-shows</p><p class="jm-m-feel"><em>Feeling</em>Hardest</p><p class="jm-m-pain"><em>Pain point</em>Needs someone in right away—and has to remember who could come</p></li></ol><h3>Key insights</h3>'+
  schedulingInsight('01','RELATIONSHIPS','When she schedules, she is managing relationships—not just allocating time.','She places steady, close students first, then those with the fewest available times; every student needs at least two lessons a month with their own instructor, and some want 5–8. Keeping steady students is her most reliable way to reach her target.','priority','',true)+
  schedulingInsight('02','COMMITMENT','The heavy scheduling work is how she keeps cancellations down.','She plans each student’s whole month, then types individual messages to 30–60 students. Planned lessons get kept; she trades her own time for students’ commitment.','exchange','',true)+
  schedulingInsight('03','MUTUAL AID','An empty slot is not one instructor’s loss—it is the whole studio’s.','Every instructor needs 120 lessons a month. Lessons she cannot fill go on a waiting list in the instructors’ group for others to pick up, and open slots should be filled right away. Scheduling is really instructors sharing out time together.','mutual','',true))+
 section('opportunity','03','PRODUCT STRATEGY','Product strategy: the MVP goes as far as the cover system',
  p('From the three insights, I made three assumptions before building:')+'<ol class="pil-assume"><li><b>01</b><span>If the system drafts by rule and she adjusts by her own priorities, it can replace hand scheduling.</span></li><li><b>02</b><span>A monthly draft plus one-tap sharing will lighten her scheduling and messaging load.</span></li><li><b>03</b><span>Sharing waiting lists between instructors will make cover smoother.</span></li></ol>'+p('So version one was scoped like this:')+
  '<div class="pil-scope"><div class="kds-scope-layout"><div class="kds-scope-rings pil-rings" role="img" aria-label="Three nested rings: the centre is single-instructor auto-scheduling with ready-made share messages and the middle ring is the cover system, both in the MVP; the outer ring—push notifications, leave and check-in, instructor pay—comes later."><div class="kds-scope-outer"><span>03 / LATER</span><strong>Push · leave &amp; check-in<br>Instructor pay</strong></div><div class="kds-scope-middle"><span>02 / MVP</span><strong>Cover system</strong></div><div class="kds-scope-center"><span>01 / MVP</span><strong>Auto-scheduling</strong><strong>Ready-made messages</strong></div></div><div class="kds-scope-legend"><div><span class="kds-scope-dot kds-scope-dot--now"></span><div><small>01 / MVP</small><strong>Single-instructor auto-scheduling + ready-made messages</strong><p>Rules draft the month; each student gets a ready-made message to copy into LINE instead of typing it out.</p></div></div><div><span class="kds-scope-dot pil-dot-mvp2"></span><div><small>02 / MVP</small><strong>Cover system</strong><p>Unfillable lessons become a cover list shared to the instructors’ group so others can take them. Cover is one of the biggest pain points—scheduling alone would not remove the real burden—so it is in the MVP.</p></div></div><div><span class="kds-scope-dot kds-scope-dot--future"></span><div><small>03 / LATER</small><strong>Proactive push, leave &amp; check-in, instructor pay</strong><p>The system notifies students and instructors through LINE directly; students request leave and check in within the system; instructor pay is calculated from lessons actually taught.</p></div></div></div></div></div>')+
 section('highlights','04','DESIGN & BUILD','Design and build: turning scheduling rules into cross-role coordination','<p class="schedule-highlight-intro">In the order she works: auto-schedule → review and adjust → notify via LINE → cover and fill-ins.</p>'+'<article class="hl-row hl-row--pil"><div class="hl-copy"><h3><span class="h-num">01</span>One-tap auto-scheduling drafts the whole month</h3><dl><div><dt>PROBLEM</dt><dd>The instructor plans every student’s month by hand—about 2–3 hours a month.</dd></div><div><dt>DESIGN</dt><dd>Tapping Auto-schedule drafts the month from availability, remaining lessons, spacing and conflicts.</dd></div><div><dt>INTERACTION</dt><dd>Start scheduling → check who has submitted → Auto-schedule; each student shows their scheduled lessons.</dd></div></dl><p class="hl-skills">Domain Modeling × Rule-based Product Design</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-auto.jpg?v=1"><source src="./assets/pilates-hl-auto.mp4?v=1" type="video/mp4"></video></div><figcaption>Tap Auto-schedule and every student’s month is drafted</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><h3><span class="h-num">02</span>Review each student’s timetable, then switch to the instructor’s view</h3><dl><div><dt>PROBLEM</dt><dd>A student\'s calendar alone cannot reveal the instructor\'s full capacity; a whole-week calendar alone can obscure an individual student\'s constraints.</dd></div><div><dt>DESIGN</dt><dd>Provide student-month and instructor-week views over the same scheduling information, allowing reviews at both individual and system levels.</dd></div><div><dt>INTERACTION</dt><dd>Search for a student and check scheduled sessions and availability, then open the instructor\'s weekly overview to assess overall occupancy.</dd></div></dl><p class="hl-skills">Information Architecture × Interaction Design</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-p2.jpg?v=2"><source src="./assets/pilates-hl-p2.mp4?v=2" type="video/mp4"></video></div><figcaption>A student’s available times, then the instructor’s whole week</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><h3><span class="h-num">03</span>A ready-made LINE message for every student</h3><dl><div><dt>PROBLEM</dt><dd>After scheduling she types individual messages to 30–60 students.</dd></div><div><dt>DESIGN</dt><dd>Each student gets a timetable image and an editable message listing this month’s dates, times and instructor.</dd></div><div><dt>INTERACTION</dt><dd>Confirm and share → check the text → pick recipients in LINE; it then shows as shared.</dd></div></dl><p class="hl-skills">Content Design × Workflow Automation</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-share.jpg?v=1"><source src="./assets/pilates-hl-share.mp4?v=1" type="video/mp4"></video></div><figcaption>The message fills in dates, times and instructor—share it via LINE</figcaption></figure></article><article class="hl-row hl-row--pil"><div class="hl-copy"><h3><span class="h-num">04</span>Share the cover list in one tap, fill open slots right away</h3><dl><div><dt>PROBLEM</dt><dd>Unfillable lessons go on a waiting list posted to the group; when a student drops out, the instructor has to remember who could come.</dd></div><div><dt>DESIGN</dt><dd>Lessons needing cover become a cover list automatically; when picking a time, the instructors available then are shown; when a slot opens, students who picked that time are listed.</dd></div><div><dt>INTERACTION</dt><dd>Cancel a lesson → the cover list appears → share it to the group via LINE; pick a cover instructor right when choosing a time; for an open slot tap “+ Make-up” → “Add” a student.</dd></div></dl><p class="hl-skills">Workflow Design × Service Coordination</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/pilates-hl-cover.jpg?v=2"><source src="./assets/pilates-hl-cover.mp4?v=2" type="video/mp4"></video></div><figcaption>Share the cover list to the group; fill an open slot with one tap (sample data)</figcaption></figure></article>'+'<div class="schedule-live-demo" id="try-demo"><div class="schedule-live-copy"><span>TRY THE PRODUCT / INTERACTIVE DEMO</span><h3>The production flow, without the LINE login</h3><p>The production code with only the LINE login removed and sample data in place. Try: Start scheduling → Auto-schedule → Confirm and share.</p><a href="./pilates-demo/teacher/" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese</small></div><div class="schedule-live-stage"><div class="pil-view-switch" role="tablist" aria-label="切換視角"><button type="button" role="tab" data-pil-view="teacher" aria-selected="true">👩‍🏫 Instructor</button><button type="button" role="tab" data-pil-view="student" aria-selected="false">🙋‍♀️ Student</button></div><div class="schedule-live-frame"><iframe data-pil-frame="teacher" src="./pilates-demo/teacher/" title="Pilates scheduling instructor demo" loading="lazy"></iframe><iframe data-pil-frame="student" data-src="./pilates-demo/?t=t1" title="Pilates scheduling student demo" hidden></iframe></div></div></div>')+
 section('reflection','05','OUTCOME & REFLECTION','Outcome & reflection: the system worked, but the instructor would not adopt it',
  '<p class="pil-outcome-lead">After the demo she said: <strong>“It honestly feels pretty good, but there are just so many variables. Am I supposed to teach every student one by one?”</strong>She saw the value but worried about teaching every student a new tool and how switching might affect students, so she has not adopted it. I had verified whether it could schedule—not whether it was worth using.</p><div class="case-close case-close--plain"><article><div class="cc-body"><h3>Six reasons she would not adopt it overturned my three assumptions</h3><div class="schedule-hypo-check"><table><thead><tr><th>My assumption</th><th>After the demo</th><th>Why she would not adopt it</th></tr></thead><tbody><tr><th scope="row"><span>01</span>A rule-based draft she adjusts can replace hand scheduling</th><td><em class="hc-up">Not trusted</em></td><td>She believes scheduling by hand copes better with all the variables.</td></tr><tr><th scope="row"><span>02</span>A monthly draft plus one-tap sharing will lighten her load</th><td><em class="hc-no">Overturned</em></td><td>2–3 hours a month is still acceptable to her; switching tools touches the student experience, which she is wary of, and she would have to explain the tool to each student.</td></tr><tr><th scope="row"><span>03</span>Sharing waiting lists between instructors will make cover smoother</th><td><em class="hc-no">Overturned</em></td><td>Cover runs on back-and-forth in LINE and is hard to move into a product—running two tools is worse; the instructors are not close, so getting everyone on board is hard.</td></tr></tbody></table><p>All six reasons point to the same thing: the barrier was not the features but the cost of adopting them.</p></div></div></article><article><div class="cc-body"><h3>Next time, ask what switching costs before asking whether it works well</h3><p>I spent my effort making the system schedule correctly, without first weighing what switching would cost her. When I evaluate a product opportunity now, I add three steps:</p><ul><li><strong>Map the existing tool ecosystem:</strong> she runs on LINE and the instructors’ group; a new product should fit into that flow, not start a parallel one.</li><li><strong>Run the smallest adoption test first:</strong> e.g. offer only a copyable LINE message and see whether she uses it each month before building a full system.</li><li><strong>Find who carries the risk:</strong> a scheduling mistake lands on her in front of students; reduce her risk first, then talk about saving time.</li></ul></div></article></div>'),



 kiosk:()=>
 section('overview','01','OVERVIEW','When KIOSK sales fell short, how could research inform the next product decisions?',
  p('The company had separate ordering and payment equipment and planned a next-generation integrated kiosk. Rather than transferring the old UI unchanged, the team needed to understand differences in restaurant menus, operational needs, and the relationship between onscreen prompts and physical payment hardware.')+
  ''+
  '<figure class="scenario-figure"><img src="./kiosk-scenario.png" alt="Conceptual integrated kiosk with display and payment hardware"><figcaption>Use scenario | how the screen relates to the physical payment hardware.</figcaption></figure>')+
 section('research','02','RESEARCH FRAMEWORK','Three research questions and the evidence behind them',
  '<div class="research-question-grid">'+
  '<div id="rq-1"><b class="rq-num">01</b><strong>What functions and flows do different restaurant formats need?</strong><div class="rq-decision"><b>Method</b>Desk research + an exploratory scan of 40 stores across ~10 categories</div><div class="rq-value"><b>Where the answer is</b><a class="rq-link rq-link--wide" href="#kiosk-market">Market focus <span aria-hidden="true">↓</span></a></div></div>'+
  '<div id="rq-2"><b class="rq-num">02</b><strong>Which important capabilities are missing against competitors?</strong><div class="rq-decision"><b>Method</b>Competitive analysis of 7 competitors: features, interfaces and flows</div><div class="rq-value"><b>Where the answer is</b><a class="rq-link" href="#kdec-1">Decision 01 · Add-on entry <span aria-hidden="true">↓</span></a></div></div>'+
  '<div id="rq-3"><b class="rq-num">03</b><strong>Where do merchants report operating difficulties and unmet needs?</strong><div class="rq-decision"><b>Method</b>Interviews with 7 store managers, plus earlier interview data</div><div class="rq-value"><b>Where the answer is</b><a class="rq-link" href="#kdec-2">Decision 02 · Payment guidance <span aria-hidden="true">↓</span></a><a class="rq-link" href="#kdec-3">Decision 03 · Set switching <span aria-hidden="true">↓</span></a></div></div></div>'+
  '<div class="kiosk-market-restored"><div class="kiosk-market-final" id="kiosk-market"><div class="kiosk-market-final-head"><span>MARKET FOCUS / TARGET FORMATS</span><h3>From a broad market to priority restaurant formats</h3><p>An exploratory scan of 40 stores across roughly ten formats helped identify restaurant types worth investigating further. The direction still needs validation with merchants.</p></div><div class="kiosk-market-final-main"><div class="market-conclusion"><div class="market-sizing market-sizing--circles"><div class="market-sizing-tam"><span>TAM</span><strong>Restaurants needing self-service ordering</strong><div class="market-sizing-sam"><span>SAM</span><strong>Formats current product could serve</strong><div class="market-sizing-focus"><span>TO VALIDATE</span><strong>Candidate formats</strong></div></div></div></div></div><div class="kiosk-market-screening"><h4>What makes a merchant a better fit?</h4><div class="kiosk-screening-item"><h5><span class="h-num">01</span>High transaction frequency</h5><p>Concentrated peak-hour orders and a need to keep ordering quick.</p></div><div class="kiosk-screening-item"><h5><span class="h-num">02</span>Standardized ordering flow</h5><p>Relatively consistent menus and steps that self-service can support.</p></div><div class="kiosk-screening-item"><h5><span class="h-num">03</span>Under NT$300</h5><p>An initial business screening threshold, not a fact about every target format.</p></div></div></div><div class="market-compare kiosk-market-final-stats"><div><span>40</span><strong>Stores</strong><small>Exploratory scan</small></div><div><span>10</span><strong>Formats</strong><small>Broad menu-based types</small></div><div><span>2</span><strong>Focus areas</strong><small>Japanese specialty / beverages</small></div></div><div class="evidence-details kiosk-market-final-chart is-open"><div class="market-chart"><div class="market-chart-head"><h6>Observed KIOSK adoption by format</h6><p>Higher bars show more observed brands, not greater product priority.</p></div><div class="market-bars"><div class="market-bar-row"><span>Chinese casual eateries</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:100%"></div></div><strong>7</strong></div><div class="market-bar-row"><span>Japanese specialty</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:100%"></div></div><strong>7</strong></div><div class="market-bar-row"><span>Fast food</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:86%"></div></div><strong>6</strong></div><div class="market-bar-row"><span>Beverage shops</span><div class="market-bar-track"><div class="market-bar market-bar-lead" style="width:86%"></div></div><strong>6</strong></div><div class="market-bar-row"><span>Western restaurants</span><div class="market-bar-track"><div class="market-bar " style="width:57%"></div></div><strong>4</strong></div><div class="market-bar-row"><span>Quick-service value meals</span><div class="market-bar-track"><div class="market-bar " style="width:43%"></div></div><strong>3</strong></div><div class="market-bar-row"><span>Noodle shops</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div><div class="market-bar-row"><span>Unmanned ramen</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div><div class="market-bar-row"><span>Cafés</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div><div class="market-bar-row"><span>Other</span><div class="market-bar-track"><div class="market-bar " style="width:29%"></div></div><strong>2</strong></div></div><p class="market-chart-note">The bar values count observed KIOSK-adopting brands by format, a different unit from the 40-store exploration; do not add them or generalize nationwide.</p></div></div></div></div><h3>Merchant interviews</h3><div class="research-audience"><div class="research-audience-summary"><div class="research-audience-count"><strong>07</strong><span>Managers across four brands</span></div><div class="interview-brand-logos" aria-label="Interviewed restaurant logos"><img src="./kiosk-logo-mini-mono.svg" alt="mini STEAK HOUSE"><img src="./kiosk-logo-ippudo-mono.svg" alt="Ippudo"><img src="./kiosk-logo-lugu-mono.svg" alt="Fighting Chicken"><img src="./kiosk-logo-kokkio-mono.svg" alt="KOKKIO"></div></div><p>Representing Noble Family Steakhouse, KOKKIO, Ippudo, and Fighting Chicken. I synthesized their reports of customer behavior, plus support tickets and historical data, into user needs.</p></div><h3>Key insights</h3><article class="insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">01</em></span><h4>Onscreen payment instructions and physical hardware are disconnected</h4><p>Managers said customers more often need help at payment than while choosing dishes. Attention stays on the screen, so cash, card or contactless modules elsewhere on the machine are missed. A manager said: <strong>“I always have to tell them to put the money into the glowing blue spot.”</strong></p></div><figure><img loading="lazy" src="./kiosk-visibility.png" alt="Line of sight from screen to payment hardware"></figure></article><article class="insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">02</em></span><h4>A single menu structure cannot fit every restaurant format</h4><p>Customers know fast-food sets well, so some options can be preselected; other meals need their contents shown first. One fixed choice sequence for every store limits fit. A steakhouse asked: <strong>“Could required meal options be selected by default?”</strong></p></div><figure><img loading="lazy" src="./kiosk-menu-simple.svg" alt="Different menu structures by format"></figure></article><article class="insight-feature insight-feature--decision"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">03</em></span><h4>Switching from an item to a set requires redundant work</h4><p>The existing product treated single items and sets as separate products, so changing one meant deleting it and choosing again. A manager said: <strong>“Customers often decide to upgrade at the end, so I ask them first.”</strong></p></div><figure><img loading="lazy" src="./kiosk-decision-revision.png" alt="Switching from item to set"></figure></article><div class="kiosk-comp" id="kiosk-comp"><h3>Competitive analysis</h3><p>Seven kiosk competitors compared on features, interface and flow. Percentages show how many offer each feature; items marked “also in interviews” came up in merchant interviews too.</p><table><thead><tr><th>Feature</th><th>Share of competitors</th><th>Notes</th></tr></thead><tbody><tr><th scope="row">Add-on flow <em class="kc-int">also in interviews</em></th><td class="kc-pct">71%</td><td>iChef reports about 50% of customers add items once enabled</td></tr><tr><th scope="row">Membership</th><td class="kc-pct">71%</td><td>Eats365 says it brings customers back</td></tr><tr><th scope="row">Recommended tags</th><td class="kc-pct">57%</td><td>incl. Hsing Yi Hsin (~20% of Taiwan POS)</td></tr><tr><th scope="row">Popular-item ranking</th><td class="kc-pct">—</td><td>Dianxiaoer and Uber Eats</td></tr><tr><th scope="row">Back to ordering from payment <em class="kc-int">also in interviews</em></th><td class="kc-pct">100%</td><td></td></tr><tr><th scope="row">Separate invoice/carrier page <em class="kc-int">also in interviews</em></th><td class="kc-pct">85%</td><td></td></tr><tr><th scope="row">Category sidebar <em class="kc-int">also in interviews</em></th><td class="kc-pct">53%</td><td>of 26 brands have more than 5 categories</td></tr><tr><th scope="row">Multiple languages <em class="kc-int">also in interviews</em></th><td class="kc-pct">85%</td><td>all include English; 66% offer Chinese, English and Japanese</td></tr><tr><th scope="row">Animated primary buttons <em class="kc-int">also in interviews</em></th><td class="kc-pct">—</td><td>Dianxiaoer, Hsing Yi Hsin</td></tr><tr><th scope="row">Payment location vs. machine <em class="kc-int">also in interviews</em></th><td class="kc-pct">—</td><td>Dianxiaoer, McDonald’s</td></tr></tbody></table></div>')+
 section('solutions','03','KEY PRODUCT DECISIONS','Three product decisions shaped by research',
 
 "<div class=\"research-question-grid kiosk-decision-rows\"><div id=\"kdec-1\"><b class=\"rq-num\">01</b><strong>Make add-ons discoverable at the right moment</strong><div class=\"rq-decision\"><b>Finding</b>71% of competitors offer an add-on entry, which points to an opportunity to offer complementary items, but direct consumer demand was not established.<a class=\"rq-back\" href=\"#rq-2\">Answers question 02 ↑</a></div><div class=\"rq-value\"><b>Decision</b>Provide a clear add-on entry during selection; any effect on average order value still needs post-launch validation.<a class=\"dec-look\" href=\"#hl-addon\">See it in action <span aria-hidden=\"true\">↓</span></a></div></div><div id=\"kdec-2\"><b class=\"rq-num\">02</b><strong>Connect on-screen guidance to physical payment hardware</strong><div class=\"rq-decision\"><b>Finding</b>Merchant managers described customers focusing on the screen and struggling to locate cash, card, or contactless payment modules.<a class=\"rq-back\" href=\"#rq-3\">Answers question 03 ↑</a></div><div class=\"rq-value\"><b>Decision</b>Map payment instructions to the actual module locations to potentially reduce staff assistance. It sits in the main flow, interrupts the transaction, and pulls staff in, so it became the top priority.<a class=\"dec-look\" href=\"#hl-pay\">See it in action <span aria-hidden=\"true\">↓</span></a></div></div><div id=\"kdec-3\"><b class=\"rq-num\">03</b><strong>Switch between items and sets without starting over</strong><div class=\"rq-decision\"><b>Finding</b>Earlier interviews found that upgrading a single item to a set often required deleting it and repeating choices.<a class=\"rq-back\" href=\"#rq-3\">Answers question 03 ↑</a></div><div class=\"rq-value\"><b>Decision</b>Let customers switch within the existing selection, reducing repetitive work and the risk of abandoning an order.<a class=\"dec-look\" href=\"#hl-combo\">See it in action <span aria-hidden=\"true\">↓</span></a></div></div></div>")+
 section('validation','04','DESIGN & VALIDATION','From design recommendations to early usability feedback',
  '<div class="design-phase design-phase--proposal"><article class="hl-row" id="hl-pay"><div class="hl-copy"><h3>Guide people to the physical payment module</h3><p class="hl-role"><b>My role</b>Proposed independently; the PM adopted it for prototyping</p><p>Abstract cash or card icons cannot show where the machine accepts payment. I proposed an illustration of the whole device with the relevant slot highlighted, so people can map the screen to the hardware.</p></div><figure class="hl-clip ba ba--pay" data-ba><div class="ba-seg"><button type="button" data-v="before" class="on">BEFORE<i></i></button><button type="button" data-v="after">AFTER<i></i></button></div><div class="ba-stage"><div class="ba-pane" data-p="before"><div class="hl-clip-frame ba-still"><img src="./kiosk-payment-before.png" alt=""></div></div><div class="ba-pane" data-p="after" hidden><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-pay.jpg?v=1"><source src="./assets/kiosk-hl-pay.mp4?v=1" type="video/mp4"></video></div></div></div><figcaption class="ba-cap" data-p="before">Before: the screen only described the action, not where the module is.</figcaption><figcaption class="ba-cap" data-p="after" hidden>After: the camera moves to the coin slot, then the note acceptor</figcaption></figure></article><article class="hl-row" id="hl-combo"><div class="hl-copy"><h3>Switch between a single item and a meal set</h3><p class="hl-role"><b>My role</b>Team idea; I helped assess and design it</p><p>Earlier research found the existing system treated single items and sets as separate products, so changing your mind meant deleting and choosing again.</p><p>The redesign adds a one-tap upgrade/revert on the same product page, with sides adjusted on the same screen.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-combo.jpg?v=1"><source src="./assets/kiosk-hl-combo.mp4?v=1" type="video/mp4"></video></div><figcaption>Upgrading to a set and adjusting sides on the product page</figcaption></figure></article><article class="hl-row" id="hl-addon"><div class="hl-copy"><h3>Add-on purchase screen</h3><p>A separate add-on screen before checkout presents item photos, prices, and quantity controls.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kiosk-hl-addon.jpg?v=1"><source src="./assets/kiosk-hl-addon.mp4?v=1" type="video/mp4"></video></div><figcaption>The add-on screen appears before payment; add items or skip</figcaption></figure></article><div class="kiosk-live-demo" id="try-demo"><div class="kiosk-live-copy"><span>TRY THE PROTOTYPE / FREE PLAY</span><h3>Walk through the redesigned ordering flow</h3><p>Order, upgrade to a set, add items, and follow the payment guidance end to end. Menu and payments are simulated.</p><a href="./kiosk-demo/index.html?v=20261029" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese</small></div><div class="kiosk-live-frame"><iframe src="./kiosk-demo/index.html?v=20261029" title="Self-ordering kiosk interactive demo" loading="lazy"></iframe></div></div></div>'+
 '<div class="design-phase design-phase--testing"><div class="phase-banner"><span>PHASE 02 / PROTOTYPE TESTING</span></div><h3>Payment felt smooth; set-meal options were less clear</h3><p>Six colleagues used the prototype on the kiosk hardware to check whether the new flow was easy to understand and to gather leads for the next round.</p><figure class="design-shot test-session-photo"><img src="./kiosk-prototype-test.png" alt="Six internal colleagues testing a kiosk prototype"></figure>'+
  '<div class="test-finding-grid"><div class="test-finding-positive"><div class="test-finding-label"><b class="test-finding-mark" aria-hidden="true">✓</b><span>POSITIVE SIGNAL</span></div><h4>Payment was relatively smooth</h4><p>Participants generally reported payment as one of the easiest task segments—a tentative signal supporting the flow.</p></div><div class="test-finding-negative"><div class="test-finding-label"><b class="test-finding-mark" aria-hidden="true">✕</b><span>USABILITY ISSUE</span></div><h4>Uniform square buttons obscured their purpose</h4><p>Every option used the same square button. After tapping “Adjust flavor” on a set meal, the buttons had no room for the set’s details, so testers could not tell which item they were adjusting—or whether they needed to adjust anything at all.</p></div></div></div>'+
  '<div class="design-phase design-phase--iteration"><div class="phase-banner"><span>PHASE 03 / SECOND ITERATION</span><strong>Test feedback led to new layouts</strong></div><div class="solution"><h3>Four layouts for different amounts and types of information</h3><p>To fix the unclear square buttons found above—and to answer insight 02, that menus must fit each store format—the second iteration created four layouts with increasing space based on <strong>information density and recognition needs</strong>—from text selections and compact images to rows and expanded cards for meal details. The system provides a default layout, while merchants can switch layouts to suit their items.</p>'+
  "<div class=\"layout-variants layout-variants--integrated\"><figure><div class=\"layout-variant-rationale\"><span>01 / Text choices</span><h4>The name is enough—no picture needed</h4><p>Toppings such as pearls or coconut jelly, recognisable by name, with a quantity stepper under each card.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-text.png?v=2\" alt=\"Name-only cards with a quantity stepper\"></figure><figure><div class=\"layout-variant-rationale\"><span>02 / Image cards</span><h4>Visual recognition without extra details</h4><p>For items best identified by a photo, showing an image, item name, and price in a compact card.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-tile.png?v=3\" alt=\"Compact image card featuring photo, name, and price\"></figure><figure><div class=\"layout-variant-rationale\"><span>03 / Compact rows</span><h4>Short meal details at a glance</h4><p>For sides or set-meal options that need a brief description within a compact layout.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-wide.png\" alt=\"Compact row showing a short meal description\"></figure><figure><div class=\"layout-variant-rationale\"><span>04 / Expanded horizontal cards</span><h4>More room for detailed meal information</h4><p>For items or set meals with richer descriptions, offering more space for readable content.</p></div><img loading=\"lazy\" src=\"./kiosk-layout-row.png\" alt=\"Expanded horizontal card with room for detailed item information\"></figure></div>"+
 '</div></div>')+
 section('reflection','05','OUTCOME & REFLECTION','Outcomes, lessons, and what comes next',
 '<div class="case-close"><div class="case-close-head"><span>CLOSING</span></div><article><b class="cc-num">01</b><div class="cc-body"><span>OUTCOME</span><h3>How research changed the decisions</h3><p>I reframed disappointing kiosk sales around merchants’ expectations of product completeness and the staff effort created when customers get stuck. Of 12 recommendations, nine were adopted as design directions. I also independently proposed aligning on-screen payment guidance with physical hardware, and the PM approved it for prototyping. These are <strong>supported design decisions</strong>, not proof of shipping or measured impact.</p></div></article><article><b class="cc-num">02</b><div class="cc-body"><span>NEXT</span><h3>From adopted decisions to demonstrated value</h3><dl class="cc-limits"><div class="cc-lh"><dt>Current gap</dt><dd>Next step</dd></div><div><dt>Needs came from seven merchant managers’ reports</dt><dd>Observe real customers paying and asking staff for help in stores.</dd></div><div><dt>The prototype was tested with six colleagues; the second iteration was not retested</dt><dd>Test the second set-selection layouts with target customers to assess errors, hesitation, and switching.</dd></div><div><dt>The 40-store market scan is an exploratory sample</dt><dd>Validate the priority store types with sales and adoption data.</dd></div><div><dt>“Adopted” does not mean shipped</dt><dd>After launch, track payment help requests, ordering completion and task time, plus add-on usage and average order value.</dd></div></dl></div></article></div>'),
 kds:()=>
 section('overview','01','CONTEXT','From an engineering demo to a deliverable KDS: first understand what kitchens need',
  ''+
  '<p>A customer expressed interest in buying a kitchen display system, so the company decided to turn an early demo—built by an engineer based on their own understanding—into a formal product. The prototype could show and process orders, but <strong>long dish names were truncated, scrolling text was hard to read, and accidentally completed orders were difficult to recover.</strong> The team first needed to clarify the initial scope and real kitchen workflows to turn the demo into a deliverable product.</p>'+
  '<figure class="scenario-figure kds-case-scenario"><img loading="lazy" src="./kds-case-hero.png" alt="Illustration of a cook using a kitchen display system"><figcaption>Kitchen use scenario.</figcaption></figure>')+
 section('research','02','DISCOVERY','How could we make evidence-based KDS decisions with a limited sample?',
  '<p>I triangulated <strong>feedback on the first-generation system, historical research, competitor comparisons, and contextual observation</strong> to understand preparation work and feature needs. LA PASTA was the only restaurant available for on-site research, so field data mainly adds working context.</p>'+
  '<div class="kds-baseline"><h3>Where the first-generation demo stood</h3><p>The engineer-built first version could already process orders, but customer feedback and a UI walkthrough surfaced three clear problems:</p><div class="kds-baseline-grid"><div><b>01</b><strong>Long dish names scroll as a marquee</strong><p>Cooks must wait for the text to finish and can miss it when busy.</p></div><div><b>02</b><strong>Only one way to view orders</strong><p>Orders appear one by one; the same item cannot be grouped for batch preparation.</p></div><div><b>03</b><strong>Mis-taps cannot be undone</strong><p>A wrong tap removes the item, so staff rely on memory to remake it.</p></div></div></div>'+
  '<div class="kds-competitor-analysis"><h3>Competitive Analysis</h3><p>I then compared competitors to see whether the market had already solved these three problems: with Protech’s first version as the baseline, against <strong>Eats365</strong> and <strong>Weiby</strong>.</p><div class="kca-wrap"><table class="kca-table"><thead><tr><th>First-gen problem</th><th>Protech</th><th>Eats365</th><th>Weiby</th><th>What it means for v2</th></tr></thead><tbody><tr><th scope="row"><b>01</b>Long names scroll as a marquee</th><td data-l="Protech">Marquee</td><td data-l="Eats365">Laid out in rows</td><td data-l="Weiby">Wrapped</td><td class="kca-out">Show full names, no marquee</td></tr><tr><th scope="row"><b>02</b>Only one way to view orders</th><td data-l="Protech">Fixed</td><td data-l="Eats365">Switch by order, category, table</td><td data-l="Weiby">By order</td><td class="kca-out">Add a switchable item view</td></tr><tr><th scope="row"><b>03</b>Mis-taps cannot be undone</th><td data-l="Protech">No recovery</td><td data-l="Eats365">Items and orders recoverable</td><td data-l="Weiby">Items recoverable</td><td class="kca-out">Completed orders can be recovered</td></tr><tr class="kca-extra"><th scope="row"><b>+</b>Wait-time alerts</th><td data-l="Protech">4 levels</td><td data-l="Eats365">2 levels + prep time</td><td data-l="Weiby">None</td><td class="kca-out">Follow Eats365: two colours (see the UI review in 04)</td></tr></tbody></table></div><div class="kds-research-turn"><strong>Takeaway:</strong> the market had already solved all three problems, so they are baseline KDS needs. The strategy for this release was an MVP that covers that baseline first. Competitors could not explain why kitchens work the way they do, though, so I went back to the kitchen to watch how staff actually prep and serve—and used that to decide how the MVP should cover the baseline.</div>'+
  '<a class="kds-compare-button" href="./kds-function-comparison.webp" target="_blank" rel="noopener noreferrer" aria-label="Open complete KDS feature comparison">View full competitor feature comparison <span aria-hidden="true">↗</span></a></div>')+
 section('user-analysis','03','USER ANALYSIS','How do kitchens batch dishes, notice changes, and determine serving order?',
  '<p>I formed an initial picture from historical tickets and requirements, then interviewed two front- and back-of-house participants at LA PASTA during one contextual site visit. The three insights below synthesize these different evidence sources.</p>'+
  ''+
  ''+
  '<h3>Key insights</h3><div class="kds-user-insights">'+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">01</em><span>BATCH PREPARATION</span></span><h4>Kitchen staff batch dishes with the same preparation process instead of finishing one order at a time</h4><p>Cooks check quantities of similar items across orders before collecting ingredients and preparing them together. The kitchen’s unit of work may be a batch of dishes, not an entire ticket.</p></div><figure class="kds-insight-figure"><div class="kds-mini-flow"><div><small>Order 01</small><strong>Dish A × 2</strong></div><div><small>Order 02</small><strong>Dish A × 1</strong></div><span class="kds-mini-arrow">↓</span><div class="kds-mini-highlight"><small>Combined preparation</small><strong>Dish A × 3</strong></div></div></figure></article>'+
  ''+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">02</em><span>INTERRUPTED ATTENTION</span></span><h4>Cooks glance at the screen intermittently; significant changes cannot rely on silent updates</h4><p>Attention stays primarily on ingredients and cooking, not the KDS. Cancellations or edits that require repeatedly checking the display risk going unnoticed.</p></div><figure class="kds-insight-figure"><div class="kds-attention-flow"><div><b>Preparing</b><span>Focus on food</span></div><div class="kds-attention-alert"><b>Order change</b><span>Must be noticed</span></div><div><b>Look back</b><span>Adjust the task</span></div></div></figure></article>'+
  ''+
  '<article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">03</em><span>EFFICIENCY & FAIRNESS</span></span><h4>Serving sequence must consider both production efficiency and customers’ waiting time</h4><p>Combining similar dishes speeds preparation, but does not mean all identical items belong in one endless batch. Orders placed far apart in time need to remain distinguishable; a total item count alone obscures who has waited longer.</p></div><figure class="kds-insight-figure"><div class="kds-time-flow"><div><small>Earlier order</small><strong>12:00</strong><span>Dish A</span></div><div><small>Next order</small><strong>12:03</strong><span>Dish A</span></div><div class="kds-time-later"><small>Later order</small><strong>12:18</strong><span>Dish A</span></div></div></figure></article><article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">04</em><span>FIRE CUE</span></span><h4>A “rush” call is not about speed—it is permission to fire</h4><p>When front of house taps “rush” on screen, the kitchen hears “you can start now”, not “hurry up”. Some tables are already full, so dishes cannot arrive too fast; front of house uses the rush button to tell the kitchen whether it can cook now—until it is pressed, the kitchen cannot start. The KDS needs a clear “ready to fire” signal, not just timers and nudges.</p></div><figure class="kds-insight-figure"><div class="kds-time-flow"><div><small>Front of house</small><strong>Table has space</strong><span>Ready for more</span></div><div><small>Front of house</small><strong>Taps “rush”</strong><span>Sends fire signal</span></div><div class="kds-time-later"><small>Kitchen</small><strong>Starts cooking</strong><span>Arrives on time</span></div></div></figure></article><article class="insight-feature kds-insight-feature"><div class="insight-feature-copy"><span class="insight-feature-kicker"><em class="insight-number">05</em><span>PHYSICAL LIMITS</span></span><h4>Software cannot be designed apart from physical constraints</h4><p>The kitchen counter is tight and a pan holds at most two portions of pasta; tables are small too, so a large puff-pastry soup and a big pasta plate arriving together crowd the table. Without a batch limit and serving-interval control, digitising the kitchen adds new bottlenecks to physical work.</p></div><figure class="kds-insight-figure"><div class="kds-time-flow"><div><small>Kitchen</small><strong>Pan holds 2 portions</strong><span>Batches need a cap</span></div><div><small>Front of house</small><strong>Small tables</strong><span>Courses need spacing</span></div><div class="kds-time-later"><small>System</small><strong>Follows physical limits</strong><span>Controls batch and pace</span></div></div></figure></article></div>'+
  '')+
 section('opportunity','04','PRODUCT DECISIONS','Team project | Translating research into actionable next-version directions',
  ''+
  '<h3>From insights to MVP delivery scope</h3><p>The insights in Section 03 map to three challenges: <strong>recognize information and prevent errors, support batched preparation, and make critical changes noticeable</strong>. With first-phase engineering constraints, the team narrowed the MVP to two delivery goals; later needs remain candidates, not commitments.</p>'+
  ""+
  "<div class=\"kds-scope-layout\"><div class=\"kds-scope-rings\" role=\"img\" aria-label=\"Three bottom-aligned nested circles: MVP in the center, later store-level rules in the middle, and network resilience on the outside.\"><div class=\"kds-scope-outer\"><span>03 / FUTURE</span><strong>Network resilience</strong></div><div class=\"kds-scope-middle\"><span>02 / LATER</span><strong>Store-specific preparation rules</strong></div><div class=\"kds-scope-center\"><span>01 / THIS MVP</span><strong>Readable preparation data<br>and error recovery</strong><strong>Batch preparation</strong></div></div><div class=\"kds-scope-legend\"><div><span class=\"kds-scope-dot kds-scope-dot--now\"></span><div><small>01 / First delivery MVP</small><strong>Core preparation tasks</strong><p>Prioritize clear information, safer actions, and batch preparation.</p></div></div><div><span class=\"kds-scope-dot kds-scope-dot--later\"></span><div><small>02 / Later workflow management</small><strong>Rules reflecting store practices</strong><p>Explore per-item batch limits (e.g. three servings) and splitting batches by order-time difference (e.g. ten minutes).</p></div></div><div><span class=\"kds-scope-dot kds-scope-dot--future\"></span><div><small>03 / Future resilience</small><strong>Handling network interruptions</strong></div></div></div></div>"+
  ""+
  "<div class=\"kds-proactive-story\"><span>PROACTIVE DESIGN REVIEW</span><h3>When the UI drifted from real kitchen needs, I initiated a revision</h3><p>During the project I noticed that parts of the initial screen hierarchy and interaction patterns did not sufficiently reflect the research: kitchen staff need to scan information quickly and recognize critical states. I proactively reviewed the screens, proposed five specific improvements, and discussed the revisions with the UX designer responsible for the production UI.</p><p><strong>Outcome:</strong> The team adopted all five recommendations, and the production UI owner updated the design.</p></div>"+
  "<div class=\"ba ba--kds\" data-ba><div class=\"ba-main\"><div class=\"ba-seg\"><button type=\"button\" data-v=\"before\" class=\"on\">BEFORE<i></i></button><button type=\"button\" data-v=\"after\">AFTER<i></i></button></div><div class=\"ba-stage\"><div class=\"ba-pane\" data-p=\"before\"><a class=\"kds-map-img\" href=\"./kds-ui-before.png\" target=\"_blank\" rel=\"noopener noreferrer\"><img loading=\"lazy\" src=\"./kds-ui-before.png\" alt=\"Previous white KDS interface with five issues marked\"><i class=\"kds-box\" data-n=\"1\" style=\"left:18.83%;top:1.38%;width:31.57%;height:5.66%\"><b>1</b></i><i class=\"kds-box kds-box--side\" data-n=\"2\" style=\"left:23.82%;top:22.95%;width:8.32%;height:5.20%\"><b>2</b></i><i class=\"kds-box\" data-n=\"2\" style=\"left:1.15%;top:95.79%;width:37.89%;height:3.83%\"></i><i class=\"kds-box\" data-n=\"3\" style=\"left:34.79%;top:29.30%;width:30.31%;height:11.63%\"><b>3</b></i><i class=\"kds-box\" data-n=\"3\" style=\"left:2.30%;top:51.72%;width:29.39%;height:5.66%\"></i><i class=\"kds-box\" data-n=\"4\" style=\"left:1.26%;top:13.93%;width:32.49%;height:6.12%\"><b>4</b></i><i class=\"kds-box\" data-n=\"4\" style=\"left:0.00%;top:8.57%;width:100.00%;height:4.59%\"></i><i class=\"kds-box\" data-n=\"5\" style=\"left:2.18%;top:34.81%;width:30.08%;height:16.22%\"><b>5</b></i></a></div><div class=\"ba-pane\" data-p=\"after\" hidden><a class=\"kds-map-img\" href=\"./kds-ui-after.png?v=6\" target=\"_blank\" rel=\"noopener noreferrer\"><img loading=\"lazy\" src=\"./kds-ui-after.png?v=6\" alt=\"Revised dark KDS interface\"></a></div><button type=\"button\" class=\"ba-peek\"><img src=\"./kds-ui-after.png?v=6\" alt=\"\"><span>See the fix →</span></button></div></div><ol class=\"ba-list kds-map-list\"><li data-n=\"1\"><b aria-hidden=\"true\">1</b><div><span>01 / SPACE ALLOCATION</span><strong>Reduce the station selector's footprint</strong><p>Station settings change infrequently but occupy prominent screen space.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"2\"><b aria-hidden=\"true\">2</b><div><span>02 / WAITING TIME</span><strong>Simplify waiting-time colors</strong><p>Use fewer signals to support faster interpretation.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"3\"><b aria-hidden=\"true\">3</b><div><span>03 / VISUAL PRIORITY</span><strong>Reserve warning colors for real alerts</strong><p>Frequent red and orange elements compete with critical information.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"4\"><b aria-hidden=\"true\">4</b><div><span>04 / INFORMATION DENSITY</span><strong>Reassess redundant details</strong><p>Revisit pending counts, area counts, and icons that repeat labels.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li><li data-n=\"5\"><b aria-hidden=\"true\">5</b><div><span>05 / NOTE USABILITY</span><strong>Prioritize note usability</strong><p>Low-frequency notes still need to be readable and actionable.</p><button type=\"button\" class=\"ba-go\">See how it was fixed →</button></div></li></ol></div>")+
 section('solutions','05','INDEPENDENT EXPLORATION','Beyond the MVP: an item view that matches preparation rhythm',
  '<p>The four design highlights below each answer an insight from Section 03: batch preparation, not missing changes during glances, and balancing efficiency with wait time.</p>'+
  '<article class="hl-row hl-row--kds"><div class="hl-copy"><h3><span class="h-num">01</span>Switch between order and item views</h3><p>The order view tracks each ticket; the category and item views total the same dish across orders so it can be made in one batch, while every portion keeps its original order number.</p><p>Cooks check items first and then send them with Batch complete, so one mis-tap never clears a whole batch.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kds-hl-views.jpg?v=5" aria-label="Recording of switching between order, category and item views"><source src="./assets/kds-hl-views.mp4?v=5" type="video/mp4"></video></div></figure></article><article class="hl-row hl-row--kds"><div class="hl-copy"><h3><span class="h-num">02</span>Keep a visible trace of important changes</h3><p>Cooks glance at the screen between tasks. An item cancelled at the counter does not vanish: it stays in place, highlighted and struck through, until a cook acknowledges it—so a dish already in progress never disappears without notice.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kds-hl-alert.jpg?v=5" aria-label="Recording of a cancelled item being acknowledged"><source src="./assets/kds-hl-alert.mp4?v=5" type="video/mp4"></video></div></figure></article><article class="hl-row hl-row--kds"><div class="hl-copy"><h3><span class="h-num">03</span>Recover accidentally completed items and resume preparation</h3><p>Mistakes happen under pressure. A fully checked order moves to Served automatically; if that was a mis-tap, the whole order can be restored or a single item sent back. Recovered items return in blue so cooks know they just came back.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><video autoplay muted loop playsinline preload="metadata" poster="./assets/kds-hl-recover.jpg?v=5" aria-label="Recording of restoring a served order"><source src="./assets/kds-hl-recover.mp4?v=5" type="video/mp4"></video></div></figure></article><article class="hl-row hl-row--kds"><div class="hl-copy"><h3><span class="h-num">04</span>Set preparation batches using capacity and order times</h3><p>Future exploration, not this MVP. Each item can have a per-batch limit, and orders placed too far apart start a new batch; the screen uses three portions and a ten-minute gap as examples.</p><p>How I would validate it: replay one store’s peak-hour orders, compare the longest wait and number of batches under order-by-order, unlimited aggregation and split rules, then check the values with kitchen staff against real pan capacity.</p></div><figure class="hl-clip"><div class="hl-clip-frame"><img loading="lazy" src="./kds-design-phase-two.png?v=6" alt="KDS phase-two capacity and time batching concept"></div></figure></article><div class="kiosk-live-demo kds-live-demo" id="try-demo"><div class="kiosk-live-copy"><span>TRY THE PROTOTYPE / INTERACTIVE DEMO</span><h3>Operate the kitchen display directly</h3><p>Switch between order and item views, check items off and send them with Batch complete, or restore a served order. Orders are simulated.</p><a href="./kds-demo/index.html" target="_blank" rel="noopener">Open interactive demo in a new tab ↗</a><small>Interface in Traditional Chinese</small></div><div class="kiosk-live-frame kds-live-frame"><iframe src="./kds-demo/index.html" title="Kitchen display system interactive demo" loading="lazy"></iframe></div></div>'+
  '')+
 section('reflection','06','OUTCOME & REFLECTION','From market-baseline features to understanding kitchen constraints',
  ''+
  '<div class="case-close"><div class="case-close-head"><span>CLOSING</span></div><article><b class="cc-num">01</b><div class="cc-body"><span>OUTCOME</span><h3>Research backed the MVP scope; all five UI recommendations were adopted</h3><ul><li>Competitor research, historical evidence, and contextual interviews informed new MVP decisions. Development is progressing toward customer delivery.</li><li>All five information-hierarchy and interaction review recommendations were adopted and reflected in revised UI designs.</li><li>Documented LA PASTA front/back-of-house coordination, production capacity, and timing constraints for further design work.</li></ul></div></article><article><b class="cc-num">02</b><div class="cc-body"><span>NEXT</span><h3>Which steps should be automated, and which stay with people?</h3><dl class="cc-limits"><div class="cc-lh"><dt>Current gap</dt><dd>Next step</dd></div><div><dt>Field research covered one restaurant and two participants</dt><dd>Interview kitchens in other formats—fast food, beverages, set meals.</dd></div><div><dt>No post-launch usage data for the new version yet</dt><dd>After launch, track mistaken-completion recoveries and order-recognition time.</dd></div><div><dt>My batching rules (3 portions, 10 minutes) are unvalidated</dt><dd>Simulate them on historical orders, then decide which calls the system makes and which stay with staff.</dd></div></dl></div></article></div>')

 };
 const card=(p,visual)=>`<a class="work-card" href="#/case/${p.id}">${visual(p.visual)}<div class="work-info"><div><h3>${p.title}</h3><p>${({scheduling:'Pilates scheduling platform',kiosk:'Next-generation self-ordering kiosk',kds:'Kitchen display system: team research + personal concept'})[p.id]}<br>${p.type}</p></div><div class="project-number">${p.number} / 03</div></div></a>`;
 function home(projects,visual){return `<section class="identity-hero"><div class="identity-wrap"><div class="identity-caption">PORTFOLIO / 2026</div><div class="identity-title"><span>Yuan</span><figure class="identity-photo"><img src="./yuan-chi-portrait.png" alt="Portrait of Yuan Chi"><i class="corner c1"></i><i class="corner c2"></i><i class="corner c3"></i><i class="corner c4"></i></figure><span>Chi</span></div><div class="identity-details"><p>Product Manager ×<br>Product Designer</p><p>Research / Strategy / Design<br>From insight to working product</p><p>Based in Taiwan<br><a href="mailto:chi861008@gmail.com">chi861008@gmail.com ↗</a></p></div></div></section><section class="intro-portrait wrap" id="about"><div class="intro-copy"><div class="eyebrow">ABOUT ME</div><h2>Hi<span class="orange">.</span></h2><p>I am a product designer moving into product management. I break ambiguous business problems into testable assumptions, then use research, design, and working prototypes to help teams make trade-offs.</p><p>From B2B restaurant systems to building my own scheduling platform, I care about choosing a problem worth solving—and making the solution tangible.</p><a class="intro-link" href="#/about">More about me <span>↗</span></a></div><div class="intro-visual"><img src="./yuan-chi-portrait.png" alt="Portrait of Yuan Chi"><div class="orbit-word">DESIGN · RESEARCH · PRODUCT · BUILD ·</div></div></section><section class="section-space wrap" id="work"><div class="section-head selected-head"><div><div class="eyebrow">SELECTED WORK / 2026</div><h2>Works record<span class="orange">.</span></h2></div><p>Three cases: research that shaped product decisions, a 0→1 build that taught me to re-scope, and team research extended into my own concept.</p></div><div class="work-grid identity-works">${projects.map(x=>card(x,visual)).join('')}</div></section><section class="dark-band"><div class="wrap"><div class="eyebrow">THE WAY I THINK</div><h2>Fall in love with the problem, not the solution.</h2><p>I look for opportunities in evidence, connect user and business needs, and make abstract ideas testable through working products.</p><a href="mailto:chi861008@gmail.com">Let’s connect ↗</a></div></section>`;}
 function about(){return `<div class="wrap"><section class="case-top"><a class="back-link" href="#/">← HOME</a><div class="eyebrow" style="margin-top:75px">THE PERSON BEHIND THE WORK</div><h1>Curious.<br>Thoughtful.<br><span class="orange">Hands-on.</span></h1><p class="case-deck">A product designer with an industrial design background, moving into product management. I care less about screens alone and more about whether a problem is worth solving and which part to solve first—then I validate the answer with research and working prototypes.</p></section></div><section class="section-space wrap" id="about"><div class="about-mini"><div><div class="eyebrow">02 / ABOUT</div><h2>Curious by nature.<br>Builder by choice.</h2></div><div><p>My background spans industrial design, UX research, and digital product design across restaurant POS, self-ordering kiosks, and kitchen display systems. Moving into product management, I frame problems, set priorities, validate at the lowest cost, and build prototypes myself with AI-assisted development when needed.</p><p>I especially enjoy problem framing, finding connections across evidence, storytelling, and making complex interactions understandable.</p><div class="skills"><span class="chip">Product Discovery</span><span class="chip">Prioritization</span><span class="chip">UX Research</span><span class="chip">Product Design</span><span class="chip">Prototyping</span><span class="chip">AI-assisted Development</span></div></div></div></section><section class="dark-band"><div class="wrap"><div class="eyebrow">LET’S CONNECT</div><h2>Have a product problem worth solving?</h2><p>I'd love to connect about product management, product design, and 0→1 opportunities.</p><a href="mailto:chi861008@gmail.com">Say hello ↗</a></div></section>`;}
 const caseLimits={kiosk:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>No end customers were interviewed; needs came from seven merchant managers</b><span>Observe customers in stores after launch and track payment-help requests. “Merchant report” items are my summaries; only the “original participant quote” is verbatim.</span></li><li><b>The prototype was tested with six colleagues; the second iteration was not retested</b><span>Run a second round with real customers, comparing hesitation and errors on set options.</span></li><li><b>The 40-store market scan is an exploratory sample</b><span>Validate the priority store types with sales and adoption data.</span></li><li><b>“Adopted” does not mean shipped</b><span>After launch, track payment completion, task time, and staff interventions.</span></li></ul></details>',scheduling:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>Needs come from two instructors</b><span>Interview five instructors of different sizes to test whether scheduling time is a shared pain.</span></li><li><b>Only functional tests with sample data; the instructor has not used it yet</b><span>Run one month of real scheduling and measure manual edits and time to final.</span></li><li><b>Time saved, fairness, cancellations, and the 120-lessons target are unvalidated</b><span>Track them as post-adoption metrics.</span></li></ul></details>',kds:'<details class="limits-box"><summary>Limits of this work, and how I would close them</summary><ul><li><b>Field research covered one restaurant and two participants</b><span>Interview kitchens in other formats (fast food, beverages, set meals). “Working context” summaries are synthesized, not verbatim.</span></li><li><b>No post-launch usage data for the new version yet</b><span>Track mistaken-completion recoveries and order-recognition time.</span></li><li><b>My batching rules (3 portions, 10 minutes) are unvalidated</b><span>Simulate them with historical orders first—see section 05.</span></li></ul></details>'};
 function casePage(project,projects,visual){const next=projects[(projects.indexOf(project)+1)%projects.length],id=project.id;
 const snapshotMarkup=`<div class="case-overview-intro case-project-meta"><span>${id==='scheduling'?'Pilates Scheduling System · 2026 · Personal project':id==='kiosk'?'Next-generation Self-ordering Kiosk · Company project':'Kitchen Display System · Team project'}</span></div>`+({"scheduling": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>A Pilates instructor spent 2–3 hours a month scheduling, then kept handling absences, fill-ins and cover.</p></div><div><span>MY ROLE</span><p>Independently defined requirements and scheduling rules, designed the UX/UI, and built a working system that runs inside LINE with AI-assisted development (Next.js, Supabase, LINE LIFF).</p></div><div><span>CHALLENGE</span><p>Translate the instructor’s scheduling experience into system rules while preserving flexibility for exceptions and manual adjustments.</p></div><div><span>OUTCOME & TURN</span><p>Built a first version with auto-scheduling, sharing and cover, but the instructor did not adopt it. The barrier was not the features but the cost of adopting them.</p></div></div>", "kiosk": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>Existing KIOSK sales were below expectations. The company planned an integrated ordering-and-payment machine but did not know what the software should change first.</p></div><div><span>MY ROLE</span><p>Consumer-facing flow and UI designer; took part in the market scan, competitor analysis, seven merchant-manager interviews, and a six-person prototype test.</p></div><div><span>CHALLENGE</span><p>Prioritize improvements for the new kiosk across different restaurant needs and hardware–software constraints.</p></div><div><span>OUTCOME</span><p>Nine of 12 recommendations were adopted, including my payment-location guide. Payment was the smoothest part of the prototype test.</p></div></div>", "kds": "<div class=\"case-snapshot case-tldr\"><div><span>PROBLEM</span><p>An engineer-built KDS demo had to become a deliverable product, but the team did not know how kitchens actually work or what the first release should cover.</p></div><div><span>MY ROLE</span><p><b>Team project:</b> research synthesis, competitor analysis, field interviews, and UI review; another UX designer led the production UI.</p></div><div><span>CHALLENGE</span><p>Define the first-release scope with limited field research, balancing information readability and batch-preparation needs.</p></div><div><span>OUTCOME</span><p>All five of my UI recommendations were adopted in the revised designs, and the product moved into pre-delivery.</p></div></div>"})[id];
 const deck={scheduling:'I built a working scheduling product—then learned from the instructor’s feedback to rethink what was worth building first.',kiosk:'Using research to decide what a next-generation kiosk should change first—from merchant interviews to an adopted payment-guidance design.',kds:'Research and UI review for a team KDS redesign (all five recommendations adopted), plus my own item-view concept for batch preparation.'}[id];
 const anchors=id==='kds'?['overview','research','user-analysis','opportunity','solutions','reflection']:id==='kiosk'?['overview','research','solutions','validation','reflection']:['overview','research','opportunity','highlights','reflection'];
 const date=id==='kiosk'?'2025.11 — 2026.04':id==='kds'?'2026.06 — 2026.07':project.year;
 const datetime=id==='kiosk'?'2025-11':id==='kds'?'2026-06':'2026';
 return `<div class="wrap"><section class="case-top${id==='kiosk'?' kiosk-cover':id==='kds'?' kds-cover':' scheduling-cover'}"><a href="#/work" class="back-link">← BACK TO SELECTED WORK</a><div class="case-title-row"><h1>${project.title}<span class="orange">.</span></h1><time class="case-cover-date" datetime="${datetime}">${date}</time></div><p class="case-deck">${deck}</p><a class="try-demo-cta" href="#try-demo">Explore interaction <span aria-hidden="true">↓</span></a>${snapshotMarkup}</section><div class="case-layout"><aside class="side-index">${nav[id].map((t,i)=>`<a href="#${anchors[i]}"><b>0${i+1}</b>${t}</a>`).join('')}</aside><article class="case-article">${content[id]()}</article></div><a class="next-case" href="#/case/${next.id}"><div><small>NEXT CASE STUDY →</small><h2>${next.title}</h2></div><span>↗</span></a></div>`;
 }
 return {home,about,casePage};
})();
